// Vercel on the business's own token: every operation of Vercel's REST API (projects, deployments, logs,
// domains and DNS, env vars, teams, firewall, edge config, feature flags, storage, sandboxes…).
// actions.json is generated by `bun scripts/openapi-actions.ts vercel`; COVERAGE.md says what's left out.
import { createHash } from "node:crypto";
import type { OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";

const api: Api = {
  name: "Vercel",
  base: "https://api.vercel.com",
  tokenHelp: "vercel.com/account/settings/tokens",
  // a dead token is a 403 with invalidToken, not a 401
  deadToken: (status, body) => status === 401 || Boolean(body?.error?.invalidToken),
  // file uploads are keyed by their SHA1; work it out when it wasn't given
  upload: (file, send, headers) => {
    if (send.headers.some(([, h]) => h === "x-vercel-digest") && !headers["x-vercel-digest"])
      headers["x-vercel-digest"] = createHash("sha1").update(file.bytes).digest("hex");
  },
};

export const vercel: OwnApp = {
  app: "vercel",
  name: "Vercel",
  logo: "/logos/vercel.svg",
  keyField: {
    label: "Access token",
    help: "vercel.com/account/settings/tokens → Create Token. Pick the team's scope to reach its projects.",
    placeholder: "xxxxxxxxxxxxxxxxxxxxxxxx",
  },
  async check(key) {
    await call(api, key, { method: "GET", path: "/v2/user", query: [], headers: [] }, {});
  },
  actions: await specActions(new URL("./actions.json", import.meta.url), api),
};
